static int64 carmichael_prime_power(int64 p, int e) {
    if (p == 2) {
        if (e == 1) return 1;
        if (e == 2) return 2;
        return 1LL << (e - 2);
    } else {
        int64 r = 1;
        for (int i = 0; i < e - 1; ++i) r *= p;
        return r * (p - 1);
    }
}

static int64 lcm_ll(int64 a, int64 b) {
    return a / std::gcd(a, b) * b;
