typedef unsigned long long u64;
typedef __uint128_t u128;

static u64 gcd_u64(u64 a, u64 b) {
    while (b) {
        u64 t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static u64 mul_mod(u64 a, u64 b, u64 mod) {
    return (u128)a * b % mod;
}

static u64 pow_mod(u64 a, u64 e, u64 mod) {
    u64 r = 1 % mod;
    while (e) {
        if (e & 1) r = mul_mod(r, a, mod);
        a = mul_mod(a, a, mod);
        e >>= 1;
    }
    return r;
}

static int is_prime_u64(u64 n) {
    if (n < 2) return 0;
    static const u64 small_primes[] = {2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL};
    for (int i = 0; i < (int)(sizeof(small_primes)/sizeof(small_primes[0])); i++) {
        u64 p = small_primes[i];
        if (n % p == 0) return n == p;
    }

    u64 d = n - 1, s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        s++;
    }

    /* Deterministic for 64-bit */
    static const u64 bases[] = {2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL, 9780504ULL, 1795265022ULL};
    for (int i = 0; i < (int)(sizeof(bases)/sizeof(bases[0])); i++) {
        u64 a = bases[i] % n;
        if (a == 0) continue;
        u64 x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1) continue;
        int comp = 1;
        for (u64 r = 1; r < s; r++) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                comp = 0;
                break;
            }
        }
        if (comp) return 0;
    }
    return 1;
}

static u64 pollard_rho_f(u64 x, u64 c, u64 mod) {
    return (mul_mod(x, x, mod) + c) % mod;
}

static u64 pollard_rho(u64 n) {
    if ((n & 1ULL) == 0) return 2;
    if (n % 3 == 0) return 3;
    u64 c = 1;
    while (1) {
        u64 x = 2, y = 2, d = 1;
        while (d == 1) {
            x = pollard_rho_f(x, c, n);
            y = pollard_rho_f(pollard_rho_f(y, c, n), c, n);
            u64 diff = x > y ? x - y : y - x;
            d = gcd_u64(diff, n);
        }
        if (d != n) return d;
        c++;
    }
}

typedef struct {
    u64 p;
    int e;
} Factor;

static Factor facs[128];
static int fac_cnt = 0;

static void add_factor(u64 p) {
    for (int i = 0; i < fac_cnt; i++) {
        if (facs[i].p == p) {
            facs[i].e++;
            return;
        }
    }
    facs[fac_cnt].p = p;
    facs[fac_cnt].e = 1;
    fac_cnt++;
}

static void factor_rec(u64 n) {
    if (n == 1) return;
    if (is_prime_u64(n)) {
        add_factor(n);
        return;
    }
    u64 d = pollard_rho(n);
    factor_rec(d);
    factor_rec(n / d);
}

static int cmp_factor(const void *a, const void *b) {
    u64 x = ((const Factor*)a)->p;
    u64 y = ((const Factor*)b)->p;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static u64 lcm_u64(u64 a, u64 b) {
    return a / gcd_u64(a, b) * b;
}

static u64 ord_mod_prime_power(u64 n_mod, u64 p, int e) {
    u64 mod = 1;
    for (int i = 0; i < e; i++) mod *= p;

    if (gcd_u64(n_mod, mod) != 1) return 0; /* should not happen in valid calls */

    u64 phi = mod / p * (p - 1);

    /* factor phi */
    fac_cnt = 0;
    factor_rec(phi);
    qsort(facs, fac_cnt, sizeof(Factor), cmp_factor);

    u64 ord = phi;
    for (int i = 0; i < fac_cnt; i++) {
        u64 q = facs[i].p;
        while (ord % q == 0 && pow_mod(n_mod % mod, ord / q, mod) == 1) {
            ord /= q;
        }
    }
    return ord;
}

