def factorize(n: int):
    fac = {}
    d = 2
    while d * d <= n:
        if n % d == 0:
            c = 0
            while n % d == 0:
                n //= d
                c += 1
            fac[d] = c
        d += 1 if d == 2 else 2
    if n > 1:
        fac[n] = 1
    return fac


def euler_phi_from_factorization(fac):
    res = 1
    for p, e in fac.items():
        res *= (p - 1) * (p ** (e - 1))
    return res


def divisors_from_factorization(fac):
    divs = [1]
    for p, e in fac.items():
        cur = []
        pe = 1
        for _ in range(e + 1):
            for d in divs:
                cur.append(d * pe)
            pe *= p
        divs = cur
    return divs


def phi(n: int):
    return euler_phi_from_factorization(factorize(n))


def carmichael_prime_power(p: int, e: int):
    if p == 2:
        if e == 1:
            return 1
        if e == 2:
            return 2
        return 1 << (e - 2)
    return (p - 1) * (p ** (e - 1))


def lcm(a: int, b: int) -> int:
    return a // math.gcd(a, b) * b


def carmichael_from_factorization(fac):
    res = 1
    for p, e in fac.items():
        res = lcm(res, carmichael_prime_power(p, e))
    return res


